package main

import (
  "fmt"
  "sort"
  "sync"
)

func main() {
  jobs := []int{1, 2, 3, 4, 5, 6, 7, 8}
  const workers = 3

  in := make(chan int)
  out := make(chan int)
  var wg sync.WaitGroup

  for i := 0; i < workers; i++ {
    wg.Add(1)
    go func() {
      defer wg.Done()
      for n := range in {
        out <- n * n
      }
    }()
  }

  go func() {
    for _, j := range jobs {
      in <- j
    }
    close(in)
  }()

  go func() {
    wg.Wait()
    close(out)
  }()

  var results []int
  for r := range out {
    results = append(results, r)
  }
  sort.Ints(results)
  fmt.Println(results)
}

