package main

import (
  "context"
  "fmt"
)

func main() {
  ctx, cancel := context.WithCancel(context.Background())
  defer cancel()

  in := make(chan int)
  out := make(chan int)

  go func() {
    defer close(in)
    for i := 1; i <= 5; i++ {
      select {
      case <-ctx.Done():
        return
      case in <- i:
      }
    }
  }()

  go func() {
    defer close(out)
    for v := range in {
      select {
      case <-ctx.Done():
        return
      case out <- v * v:
      }
    }
  }()

  sum := 0
  for v := range out {
    sum += v
  }
  fmt.Println(sum)
}
